-- Warrior RP original speech and emote catalog (frFR)
local _, addon = ...
addon.localeData.frFR.texts = {
    HEROIC_STRIKE = { name = "Frappe héroïque", ziel = { "%s, considérez cela comme ma politesse d'usage.", "*surprend %s d'un coup parti d'un geste très court.*" }, gruppe = { "Vous savez pourquoi cette arme est lourde ? Elle discute rarement.", "*porte son poids vers l'avant et abat son arme avec vigueur.*", "Certains arguments n'ont pas besoin de seconde phrase.", "*engage l'épaule et laisse l'acier finir la démonstration.*" } },
    CHARGE = { name = "Charge", ziel = { "%s, essayez de ne pas me rattraper !", "*fonce droit sur %s et dévore les derniers pas.*" }, gruppe = { "Si le chemin est fermé, je prends la ligne droite.", "*baisse l'épaule et s'élance dans un nuage de poussière.*", "J'arrive ! Ce n'est pas une menace, c'est un itinéraire !", "*traverse une brèche dans un fracas d'armure.*" } },
    REND = { name = "Pourfendre", ziel = { "%s, votre armure a une question sans réponse.", "*glisse une brève taille entre deux plaques de %s.*" }, gruppe = { "Les coutures des armures cachent de petits secrets. Je suis curieux.", "*fait glisser sa lame dans une ouverture de la garde.*", "Un tailleur serait scandalisé. Moi, je suis ravi.", "*retire sa lame et cherche une nouvelle faille.*" } },
    HAMSTRING = { name = "Brise-genou", ziel = { "%s, nous finirons cette conversation ici.", "*passe de côté et frappe bas devant %s.*" }, gruppe = { "Vous enfuir ? Voilà un plan bien fragile.", "*se baisse vivement sous la garde adverse.*", "Je n'aime pas courir deux fois. Une fois suffit.", "*fauche bas et reprend immédiatement sa garde.*" } },
    THUNDER_CLAP = { name = "Coup de tonnerre", ziel = {  }, gruppe = { "Quand le sol tremble, plus besoin de tambour.", "*frappe si fort du pied que la poussière bondit.*", "Vous entendez ? Même la terre proteste.", "*écarte les bras et laisse une onde sourde courir parmi les rangs.*" } },
    CLEAVE = { name = "Enchaînement", ziel = {  }, gruppe = { "Si vous venez côte à côte, vous partagerez les ennuis.", "*décrit un vaste arc avec son arme dans la mêlée.*", "J'espère que vous avez gardé assez de place. Pas moi.", "*pivote sur un talon et prolonge l'élan d'un second mouvement.*" } },
    EXECUTE = { name = "Exécution", ziel = { "%s, la discussion s'arrête ici.", "*fixe %s durant une respiration calme, puis la lame tombe.*" }, gruppe = { "Je vous ai laissé toutes les occasions de battre en retraite.", "*attend un battement de cœur, puis abat un coup décisif.*", "Les négociations sont terminées.", "*resserre sa prise et referme la dernière ouverture.*" } },
    SUNDER_ARMOR = { name = "Fracasser armure", ziel = { "%s, votre forgeron aura des questions.", "*met à l'épreuve une couture de l'armure de %s.*" }, gruppe = { "Belle cuirasse. Dommage pour les rivets.", "*place le tranchant contre une jointure d'armure.*", "Un acier coûteux ne remplace pas une bonne garde.", "*trace du fil de la lame une ligne entre deux plaques.*" } },
    SHIELD_BLOCK = { name = "Maîtrise du blocage", ziel = {  }, gruppe = { "Il faudra frapper à la porte. Mon bouclier reste fermé.", "*tourne le bord du bouclier pour recevoir le coup.*", "Un bon bouclier écoute avant de répondre.", "*plante ses bottes au sol sans céder un pouce.*" } },
    SHIELD_BASH = { name = "Coup de bouclier", ziel = { "%s, gardez votre prochaine syllabe.", "*tente d'interrompre %s d'une poussée sèche du bouclier.*" }, gruppe = { "Chut. Voyons si je peux interrompre votre sort.", "*pousse son bouclier en avant entre deux syllabes.*", "Ma réponse à la magie possède une poignée de bois.", "*avance d'un pas et tente de percuter sans prévenir.*" } },
    TAUNT = { name = "Provocation", ziel = { "%s, regardez-moi, pas les plus faibles !", "*se plante devant %s et tape sur son bouclier pour le provoquer.*" }, gruppe = { "Par ici ! Les ennuis portent mon nom aujourd'hui.", "*frappe trois fois la poignée de son arme contre son bouclier.*", "Les autres sont occupés. Pas moi.", "*sort de la ligne et invite les ennemis à approcher.*" } },
    BATTLE_SHOUT = { name = "Cri de guerre", ziel = {  }, gruppe = { "Têtes hautes, rangs serrés ! Personne ne tombe seul !", "*bat la mesure avec la poignée contre le bouclier.*", "Vous avez des jambes pour tenir et du cœur pour résister. Servez-vous-en !", "*se dresse devant ses alliés et lève la lame.*" } },
    DEMORALIZING_SHOUT = { name = "Cri démoralisant", ziel = {  }, gruppe = { "Les premiers tremblent déjà. Les derniers suivront !", "*pousse un cri profond et rugueux du fond de la poitrine.*", "Regardez autour de vous. Pour qui vous battez-vous encore ?", "*désigne de sa lame les lignes ennemies vacillantes.*" } },
    REVENGE = { name = "Vengeance", ziel = { "%s, votre propre élan travaille pour moi.", "*arrête l'attaque de %s et répond sans attendre.*" }, gruppe = { "Merci pour l'occasion. Je vous la rends aussitôt.", "*dévie une arme et frappe dans la brèche.*", "J'oublie les visages. Jamais les coups.", "*passe directement de la parade à la riposte.*" } },
    OVERPOWER = { name = "Fulgurance", ziel = { "%s, j'accepte votre invitation.", "*se décale à peine de %s et lance une estocade.*" }, gruppe = { "Voilà une faille. Comme c'est généreux de votre part.", "*esquive le coup manqué et saisit l'angle ouvert.*", "Manquez-moi une fois, vous m'invitez à entrer.", "*transforme un faux pas adverse en riposte éclair.*" } },
    MORTAL_STRIKE = { name = "Frappe mortelle", ziel = { "%s, voilà l'instant que vous n'avez pas vu venir.", "*dirige son arme lourde vers %s avec une force terrible.*" }, gruppe = { "Je ne garde rien pour une seconde tentative.", "*saisit son arme à deux mains et engage tout son poids.*", "Certains duels se règlent en paroles. Pas celui-ci.", "*avance et conduit l'acier avec une précision implacable.*" } },
    WHIRLWIND = { name = "Tourbillon", ziel = {  }, gruppe = { "Mettez-vous donc en cercle. Cela m'arrange.", "*tourne dans la mêlée, l'arme tendue à bout de bras.*", "J'aime partager. Aujourd'hui, c'est de l'acier.", "*fait chanter la lame dans un large mouvement circulaire.*" } },
    BLOODTHIRST = { name = "Sanguinaire", ziel = { "%s, cela va devenir désagréable.", "*se rapproche vivement de %s sans ouvrir sa garde.*" }, gruppe = { "Le pouls s'emballe. La main reste sûre.", "*expire brusquement et poursuit son assaut sans relâche.*", "La colère ne rend pas mes coups imprécis.", "*se rue en avant, les yeux sauvages, la prise parfaitement mesurée.*" } },
    INTERCEPT = { name = "Interception", ziel = { "%s, les raccourcis sont ma spécialité.", "*s'élance et barre la route à %s.*" }, gruppe = { "Une avance n'est qu'un temps emprunté.", "*jaillit de la mêlée et coupe toute retraite.*", "Vous courez ? Parfait, j'avais besoin d'exercice.", "*bondit de sa position et atterrit sur le chemin de la fuite.*" } },
    PUMMEL = { name = "Volée de coups", ziel = { "%s, gardez le mot suivant pour vous.", "*entre dans le geste de %s et en brise le rythme.*" }, gruppe = { "Trop de paroles. Pas assez de garde.", "*rompt le geste d'incantation d'un coup sec et précis.*", "Vous vouliez ajouter quelque chose ? Non ? Bien.", "*désorganise le mouvement du bras d'un petit coup.*" } },
    SWEEPING_STRIKES = { name = "Attaques circulaires", ziel = {  }, gruppe = { "Pourquoi faire la moitié du travail quand toute une bataille nous attend ?", "*prolonge le premier coup en un second arc fluide.*", "Plus d'ennemis ? Moins de déplacements.", "*poursuit le mouvement de la lame à travers la mêlée.*" } },
    DEATH_WISH = { name = "Souhait mortel", ziel = {  }, gruppe = { "La raison a donné son avis. Je ne suis pas d'accord.", "*relâche un instant sa prise et choisit l'attaque.*", "Je connais le risque. Eux, peut-être pas.", "*jette un dernier regard à sa garde avant de bondir.*" } },
    RECKLESSNESS = { name = "Témérité", ziel = {  }, gruppe = { "La prudence, c'était hier. Aujourd'hui, on agit.", "*rejette l'hésitation sans lâcher son arme.*", "Vous pourrez me faire la morale demain. S'il y a un demain.", "*engage tout son corps dans une suite de coups furieux.*" } },
    LAST_STAND = { name = "Dernier rempart", ziel = {  }, gruppe = { "Jusqu'ici. Pas un pas de plus.", "*se relève péniblement et lève de nouveau le bouclier.*", "Je tiens encore debout. Voilà ma réponse.", "*replace ses jambes tremblantes dans la brèche.*" } },
    SHIELD_WALL = { name = "Mur protecteur", ziel = {  }, gruppe = { "Derrière moi ! Pas d'héroïsme solitaire !", "*ramène le bouclier contre soi et serre la ligne alliée.*", "Qui veut passer devra avoir de la patience.", "*ferme la dernière brèche entre le bouclier et l'armure.*" } },
    RETALIATION = { name = "Représailles", ziel = {  }, gruppe = { "Qui frappe doit apprécier l'écho.", "*entrouvre la garde et répond à chaque coup par l'acier.*", "Venez donc. J'ai un instant pour chacun.", "*ancre les pieds et attend les coups impatients.*" } },
    MOCKING_BLOW = { name = "Coup railleur", ziel = { "%s, montrez-moi enfin ce que vous savez faire !", "*simule une garde maladroite devant %s en ricanant.*" }, gruppe = { "Vous êtes dangereux ou simplement bruyant ?", "*abaisse trop ostensiblement la pointe et attire l'ennemi.*", "Pardon. Je vous ai pris pour un mannequin d'entraînement.", "*porte une petite taille insolente et sourit au-dessus du bouclier.*" } },
    BERSERKER_RAGE = { name = "Rage berserker", ziel = {  }, gruppe = { "La peur ? Pas de place pour elle aujourd'hui.", "*roule les épaules comme pour se débarrasser d'un poids invisible.*", "La peur peut attendre dehors. Ma fureur entre.", "*expire brutalement et fixe le combat sans ciller.*" } },
    BLOODRAGE = { name = "Rage sanguinaire", ziel = {  }, gruppe = { "La douleur est un message. Je répondrai plus tard.", "*frappe son torse du poing et rassemble son ardeur.*", "Le cœur bat encore. Cela suffit comme explication.", "*serre les dents et raidit les épaules sous l'armure.*" } },
    DISARM = { name = "Désarmement", ziel = { "%s, vos mains seraient plus sages sans acier.", "*tente de tourner le poignet armé de %s d'un mouvement précis.*" }, gruppe = { "Jolie épée. Puis-je la voir un instant ?", "*tente d'arracher l'arme adverse d'une brève torsion.*", "Voyons si je peux vous ôter cette arme.", "*tente de saisir le bras armé et de détourner le manche hors de sa ligne.*" } },
    INTIMIDATING_SHOUT = { name = "Cri d'intimidation", ziel = {  }, gruppe = { "Fuyez tant que vous connaissez encore la route !", "*lance un rugissement féroce au-dessus des têtes ennemies.*", "C'était mon avertissement poli. Le prochain sera d'acier.", "*frappe le bouclier et découvre les dents.*" } },
    CHALLENGING_SHOUT = { name = "Cri de défi", ziel = {  }, gruppe = { "TOUS SUR MOI ! J'ai de la place pour toutes vos rancunes !", "*écarte les bras et défie la ligne entière.*", "Laissez les autres ! Aujourd'hui, je suis votre problème !", "*martèle son bouclier et hurle aux assaillants.*" } },
    SLAM = { name = "Heurtoir", ziel = { "%s, tenez fermement ce qui vous appartient encore.", "*porte une lourde frappe descendante vers %s.*" }, gruppe = { "Ce n'est pas un marteau. Vous ne sentirez guère la différence.", "*lève son arme au-dessus de l'épaule et l'abat de tout son poids.*", "Un coup net vaut cinq coups timides.", "*suspend un instant le mouvement, puis frappe lourdement.*" } },
    DEVASTATE = { name = "Dévaster", ziel = { "%s, votre protection se fait rare.", "*vise encore une fois la jointure faible de l'armure de %s.*" }, gruppe = { "Déjà desserré ? Terminons le travail.", "*frappe une section d'armure déjà fragilisée.*", "Votre forgeron a visiblement économisé au mauvais endroit.", "*tapote une jointure découverte, puis frappe de nouveau.*" } },
    SHIELD_SLAM = { name = "Heurt de bouclier", ziel = { "%s, ne regardez pas seulement mon épée.", "*projette son bouclier contre %s au moment opportun.*" }, gruppe = { "Un bouclier ferme aussi les portes. Souvent à hauteur de visage.", "*arrache le bouclier de sa garde et projette le bord en avant.*", "Qui a prétendu que la défense devait être polie ?", "*bondit d'un pas et laisse parler son bouclier.*" } },
    CONCUSSION_BLOW = { name = "Bourrasque", ziel = { "%s, je vous emprunte votre empressement.", "*tente de frapper %s d'un coup bref et étourdissant.*" }, gruppe = { "Je vais essayer de vous déconcentrer.", "*tente de porter un coup lourd entre deux mouvements adverses.*", "Je vais essayer d'offrir un instant de silence à tout le monde.", "*raccourcit sa prise et tente de frapper avec une force surprenante.*" } },
    VICTORY_RUSH = { name = "Ivresse de la victoire", ziel = { "%s, je ne fais que commencer.", "*se tourne vers %s après une brève inspiration triomphante.*" }, gruppe = { "Un de moins. Les autres tiennent encore debout.", "*profite de son regain d'énergie pour repartir à l'assaut.*", "Nous fêterons cela plus tard. Quelque chose bouge encore.", "*se frappe une fois la poitrine et avance aussitôt.*" } },
    BATTLE_STANCE = { name = "Posture de combat", ziel = {  }, gruppe = { "Deux pieds bien placés séparent le courage de la sottise.", "*plante les pieds à largeur d'épaules et fait rouler sa lame.*", "Je reste prêt. Au reste du monde de décider.", "*répartit son poids entre le bras de bouclier et la main armée.*" } },
    DEFENSIVE_STANCE = { name = "Posture défensive", ziel = {  }, gruppe = { "Pour atteindre les miens, il faudra convaincre mon bouclier.", "*élargit ses appuis et lève le bouclier devant ses alliés.*", "Ce n'est pas le cri le plus fort qui gagnera aujourd'hui.", "*abaisse son centre de gravité et devient un mur derrière sa garde.*" } },
    BERSERKER_STANCE = { name = "Posture berserker", ziel = {  }, gruppe = { "Qui a dit que la colère rend aveugle n'a jamais vraiment regardé.", "*inspire profondément et prend une posture féroce.*", "Le monde est soudain très simple : en avant.", "*relâche les épaules, abaisse son arme, puis la relève vivement.*" } },
    PIERCING_HOWL = { name = "Hurlement perçant", ziel = {  }, gruppe = { "Si vous m'entendez, c'est déjà trop tard.", "*pousse un hurlement qui perce tout le vacarme alentour.*", "Non, ce n'était pas une meute de loups. Seulement moi.", "*renverse la tête et laisse monter un long cri rauque.*" } },
    SPEARING_STRIKE = { name = "Coup empalant", ziel = { "%s, il reste de la place entre vos plaques.", "*glisse la pointe dans une ouverture de la garde de %s.*" }, gruppe = { "La brèche est étroite. Ma pointe ne l'est pas.", "*avance droit devant, l'arme tendue.*", "L'armure est solide. Les angles sont plus forts.", "*tourne le poignet vers la faille et pousse la pointe.*" } },
    TACTICAL_MASTERY = { name = "Maîtrise tactique", ziel = {  }, gruppe = { "Entre le courage et la sottise, il y a de bons appuis.", "*ajuste sa position d'un rien et garde le champ de bataille en vue.*", "Un champ de bataille ne se joue pas aux dés. Il se lit.", "*observe les chemins, les ennemis et les retraites sans abaisser son arme.*" } },
}
